from typing import Annotated
from fastapi import FastAPI, Depends, Response
from fastapi.testclient import TestClient

app = FastAPI()

def modify_response(response: Response):
    response.headers["X-Custom-Header"] = "custom-value"
    return response

@app.get("/")
def endpoint(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "Hello World"}

@app.get("/alt")
def endpoint_alt(response: Response = Depends(modify_response)):
    return {"message": "Hello World Alt"}

@app.get("/regular")
def endpoint_regular(response: Response):
    return {"message": "Hello World Regular"}

client = TestClient(app)

def test_response_dependency_annotated():
    response = client.get("/")
    assert response.status_code == 200
    assert response.headers["X-Custom-Header"] == "custom-value"

def test_response_dependency_default():
    response = client.get("/alt")
    assert response.status_code == 200
    assert response.headers["X-Custom-Header"] == "custom-value"

def test_response_regular():
    response = client.get("/regular")
    assert response.status_code == 200
    # Should not have the custom header
    assert "X-Custom-Header" not in response.headers

